payload.text:
To satisfy your requests, I will perform the following updates:

1.  **Score Interaction**: I will implement a "hold to add 1" logic. Holding the score for more than 500ms will directly add a point (once). Clicking quickly will toggle the +/- menu.
2.  **Visuals**: I will significantly increase the size of the Diamond (bases) and the BSO indicators (Balls/Strikes/Outs) while keeping their layout centered.
3.  **Layout**: I will condense the **Pitch Info** section into a single horizontal row at the bottom to save vertical space.
4.  **Controls**: I will add a `Position` input field to the Lineup Editor in the control panel.

# Updated files:

## types.ts

Added `position` field to `Player` interface.

```typescript
export interface Player {
  id: string;
  name: string;
  number: string;
  stat: string; // e.g., "1-1" for batter, "P:60" for pitcher
  position?: string; // Defensive position e.g. "SS", "DH"
}

export interface Team {
  name: string; // Abbreviation e.g. "LSP"
  fullName: string;
  score: number;
  color: string;
  lineup: Player[];
  currentBatterIndex: number;
}

export interface PitchInfo {
  type: string;
  speed: string;
  unit: string;
  spinRate: string;
}

export interface GameMeta {
  leagueName: string;
  date: string;
  gameId: string;
  broadcaster: string;
}

export interface GameState {
  awayTeam: Team;
  homeTeam: Team;

  // Inning
  inning: number;
  isTop: boolean; // true = top, false = bottom

  // Count
  balls: number;
  strikes: number;
  outs: number;

  // Runners (true = occupied)
  bases: [boolean, boolean, boolean]; // 1st, 2nd, 3rd

  // Active Players
  pitcher: Player;
  batter: Player;

  // Pitch Data
  currentPitch: PitchInfo;

  // Timer
  timer: number;
  isTimerRunning: boolean;

  // Display Settings
  showPitchInfo: boolean;

  meta: GameMeta;
}

export type ActionType = 
  | { type: 'INCREMENT_BALL' }
  | { type: 'INCREMENT_STRIKE' }
  | { type: 'INCREMENT_OUT' }
  | { type: 'RESET_COUNT' }
  | { type: 'TOGGLE_BASE'; baseIndex: 0 | 1 | 2 }
  | { type: 'ADD_SCORE'; team: 'home' | 'away'; amount: number }
  | { type: 'NEXT_INNING' }
  | { type: 'SET_INNING'; value: number }
  | { type: 'UPDATE_PLAYER'; role: 'pitcher' | 'batter'; field: keyof Player; value: string }
  | { type: 'INCREMENT_PLAYER_STAT'; role: 'pitcher' | 'batter' }
  | { type: 'UPDATE_TEAM'; team: 'home' | 'away'; field: keyof Team; value: any } // value can be string or number or array
  | { type: 'UPDATE_PITCH'; field: keyof PitchInfo; value: string }
  | { type: 'SET_TIMER'; value: number }
  | { type: 'TOGGLE_TIMER' }
  | { type: 'DECREMENT_TIMER' }
  | { type: 'TOGGLE_VISIBILITY'; field: 'showPitchInfo' }
  | { type: 'NEXT_BATTER' }
  | { type: 'ADD_PLAYER_TO_LINEUP'; team: 'home' | 'away' }
  | { type: 'UPDATE_LINEUP_PLAYER'; team: 'home' | 'away'; index: number; field: keyof Player; value: string }
  | { type: 'REMOVE_PLAYER_FROM_LINEUP'; team: 'home' | 'away'; index: number }
  | { type: 'UPDATE_META'; field: keyof GameMeta; value: string };
```

