## components/Diamond.tsx

Increased size classes significantly.

```typescript
import React from 'react';

interface DiamondProps {
  bases: [boolean, boolean, boolean];
  onToggle: (baseIndex: 0 | 1 | 2) => void;
  className?: string;
  activeColor?: string;
}

export const Diamond: React.FC<DiamondProps> = ({ bases, onToggle, className = "", activeColor = "#facc15" }) => {
  // We use inline styles for the dynamic active color
  const getStyle = (active: boolean) => {
      if (!active) return {};
      return {
          backgroundColor: activeColor,
          boxShadow: `0 0 20px ${activeColor}`
      };
  };

  // Increased width/height significantly as requested
  const baseClass = (active: boolean) => 
    `w-14 h-14 lg:w-16 lg:h-16 border-[4px] border-white transform rotate-45 transition-all duration-200 cursor-pointer shadow-lg ${active ? 'scale-110' : 'bg-white/10 hover:bg-white/30'}`;

  return (
    <div className={`relative w-48 h-48 lg:w-60 lg:h-60 flex items-center justify-center ${className}`}>
      {/* 2nd Base (Top) */}
      <div 
        className={`absolute top-0 left-1/2 -translate-x-1/2 ${baseClass(bases[1])}`} 
        onClick={() => onToggle(1)}
        style={getStyle(bases[1])}
      />

      {/* 3rd Base (Left) */}
      <div 
        className={`absolute left-0 top-1/2 -translate-y-1/2 ${baseClass(bases[2])}`} 
        onClick={() => onToggle(2)}
        style={getStyle(bases[2])}
      />

      {/* 1st Base (Right) */}
      <div 
        className={`absolute right-0 top-1/2 -translate-y-1/2 ${baseClass(bases[0])}`} 
        onClick={() => onToggle(0)}
        style={getStyle(bases[0])}
      />
    </div>
  );
};
```

## components/ScoreboardDisplay.tsx

Refactored Pitch Info to single row, increased BSO sizes, implemented Long Press Score logic.

```typescript
import React, { useRef, useEffect, useState, forwardRef } from 'react';
import { GameState, ActionType, Team } from '../types';
import { Diamond } from './Diamond';
import { Timer, Plus, Minus } from 'lucide-react';

interface ScoreboardDisplayProps {
  state: GameState;
  dispatch: React.Dispatch<ActionType>;
}

// Simple Audio Context Helper
const playBeep = (freq: number, duration: number, type: 'sine' | 'square' | 'triangle' = 'sine') => {
  try {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = type;
      osc.frequency.value = freq;

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();

      // Fade out
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.00001, ctx.currentTime + duration);

      osc.stop(ctx.currentTime + duration);
  } catch (e) {
      console.error("Audio playback failed", e);
  }
};

const playChime = () => {
    playBeep(600, 0.1, 'sine');
    setTimeout(() => playBeep(800, 0.2, 'sine'), 100);
}

// Helper for Score Animation
const AnimatedScore = ({ score }: { score: number }) => {
    const [animate, setAnimate] = useState(false);
    const prevScore = useRef(score);

    useEffect(() => {
        if (score !== prevScore.current) {
            setAnimate(true);
            const timer = setTimeout(() => setAnimate(false), 500);
            prevScore.current = score;
            playChime(); // Play sound on score change
            return () => clearTimeout(timer);
        }
    }, [score]);

    return (
        <div 
          className={`flex items-center justify-center w-full h-full text-8xl lg:text-9xl xl:text-[9rem] font-display font-bold text-center cursor-pointer select-none transition-all drop-shadow-lg leading-none rounded-lg ${animate ? 'text-yellow-300 scale-125 duration-150 drop-shadow-[0_0_25px_rgba(253,224,71,0.8)]' : 'text-white duration-300'}`}
        >
          {score}
        </div>
    );
};

export const ScoreboardDisplay = forwardRef<HTMLDivElement, ScoreboardDisplayProps>(({ state, dispatch }, ref) => {
  const [showInningControls, setShowInningControls] = useState(false);
  const [showScoreControlsHome, setShowScoreControlsHome] = useState(false);
  const [showScoreControlsAway, setShowScoreControlsAway] = useState(false);

  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const ignoreTimerClickRef = useRef(false);

  // Score Long Press Logic refs
  const scorePressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const ignoreScoreClick = useRef(false);

  // Audio Effects for Timer
  useEffect(() => {
    if (!state.isTimerRunning) return;

    if (state.timer === 8) {
        playBeep(800, 0.2, 'sine'); // Warning beep
    } else if (state.timer === 0) {
        playBeep(300, 0.8, 'square'); // Time up buzzer
    }
  }, [state.timer, state.isTimerRunning]);

  // Timer Click Logic
  const handleTimerMouseDown = () => {
    ignoreTimerClickRef.current = false;
    timerRef.current = setTimeout(() => {
      dispatch({ type: 'SET_TIMER', value: 20 }); 
      if (state.isTimerRunning) dispatch({ type: 'TOGGLE_TIMER' }); 
      ignoreTimerClickRef.current = true;
    }, 800);
  };

  const handleTimerMouseUp = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  };

  const handleTimerClick = () => {
    if (!ignoreTimerClickRef.current) {
        dispatch({ type: 'TOGGLE_TIMER' });
    }
    ignoreTimerClickRef.current = false;
  };

  // Score Interaction Logic
  const handleScoreMouseDown = (team: 'home' | 'away') => {
      ignoreScoreClick.current = false;
      scorePressTimer.current = setTimeout(() => {
          // Long press action: Add 1 point immediately
          dispatch({ type: 'ADD_SCORE', team, amount: 1 });
          ignoreScoreClick.current = true; // Prevent menu toggle on mouse up
      }, 500); // 500ms for long press
  };

  const handleScoreMouseUp = () => {
      if (scorePressTimer.current) {
          clearTimeout(scorePressTimer.current);
          scorePressTimer.current = null;
      }
  };

  const handleScoreClick = (team: 'home' | 'away') => {
      // If long press triggered, do NOT open menu
      if (ignoreScoreClick.current) {
          ignoreScoreClick.current = false;
          return;
      }

      // Short press: Toggle Menu
      if (team === 'home') {
          setShowScoreControlsHome(!showScoreControlsHome);
          setShowScoreControlsAway(false);
      } else {
          setShowScoreControlsAway(!showScoreControlsAway);
          setShowScoreControlsHome(false);
      }
  };

  const handleScoreMouseLeave = () => {
      // Clear timer if mouse leaves area
      if (scorePressTimer.current) {
          clearTimeout(scorePressTimer.current);
          scorePressTimer.current = null;
      }
      // Auto hide controls logic
      setTimeout(() => {
          setShowScoreControlsHome(false);
          setShowScoreControlsAway(false);
      }, 3000);
  };

  const handleBallClick = () => dispatch({ type: 'INCREMENT_BALL' });
  const handleStrikeClick = () => dispatch({ type: 'INCREMENT_STRIKE' });
  const handleOutClick = () => dispatch({ type: 'INCREMENT_OUT' });

  const handleBatterClick = () => dispatch({ type: 'NEXT_BATTER' });
  const handlePitcherStatClick = () => dispatch({ type: 'INCREMENT_PLAYER_STAT', role: 'pitcher' });

  const awayRole = state.isTop ? 'AT BAT' : 'PITCHING';
  const homeRole = state.isTop ? 'PITCHING' : 'AT BAT';

  const awayPlayer = state.isTop ? state.batter : state.pitcher;
  const homePlayer = state.isTop ? state.pitcher : state.batter;

  const activeBaseColor = state.isTop ? state.awayTeam.color : state.homeTeam.color;

  const TeamLogo = ({ team }: { team: Team }) => (
    <div 
        className="w-16 h-16 lg:w-20 lg:h-20 rounded-full flex items-center justify-center shadow-lg border-2 border-white/20 relative z-10 shrink-0"
        style={{ backgroundColor: team.color }}
    >
        <span className="text-3xl lg:text-4xl font-display font-bold text-white drop-shadow-md">{team.name.substring(0, 1)}</span>
    </div>
  );

  return (
    <div ref={ref} className="w-full h-full bg-slate-900 select-none flex flex-col justify-center overflow-hidden">
      {/* Main Container - Full 16:9 Aspect ratio handled by parent scale, remove max-width constraint */}
      <div className={`bg-slate-900 border-4 border-slate-700 rounded-xl overflow-hidden shadow-2xl relative font-display text-white w-full mx-auto flex flex-col h-full`}>

        {/* Top Section: Scoreboard Main (Expandable) */}
        <div className={`flex flex-row flex-1 min-h-0`}>

          {/* LEFT: Away Team */}
          <div className="flex-1 border-r-2 border-slate-700 relative group overflow-hidden">
             <div className="absolute inset-0 opacity-20 transition-colors duration-500" style={{ backgroundColor: state.awayTeam.color }}></div>

            <div className="flex h-full relative z-10 p-4 lg:p-5 flex-col justify-between">
                <div className="flex justify-start items-start gap-4">
                  <div className="shrink-0 relative">
                     <TeamLogo team={state.awayTeam} />
                     {state.isTop && <div className="absolute -bottom-2 -right-2 w-5 h-5 bg-yellow-400 rounded-full animate-pulse shadow-[0_0_12px_rgba(250,204,21,1)] border-2 border-slate-900 z-20" />}
                  </div>

                  <div className="flex flex-col items-start min-w-0 pt-1">
                     <span className="text-5xl lg:text-6xl xl:text-7xl font-bold text-white tracking-tight drop-shadow-sm leading-none truncate">{state.awayTeam.name}</span>
                     <span className="text-sm lg:text-base text-slate-300 font-semibold tracking-wide uppercase truncate max-w-full pl-1">{state.awayTeam.fullName}</span>
                  </div>
                </div>

                {/* Score Area */}
                <div 
                   className="flex-1 flex items-center justify-center relative group/score px-8"
                   onMouseDown={() => handleScoreMouseDown('away')}
                   onMouseUp={handleScoreMouseUp}
                   onTouchStart={() => handleScoreMouseDown('away')}
                   onTouchEnd={handleScoreMouseUp}
                   onClick={() => handleScoreClick('away')}
                   onMouseLeave={handleScoreMouseLeave}
                >
                   <AnimatedScore score={state.awayTeam.score} />

                   {/* Popover Controls for Score */}
                   {showScoreControlsAway && (
                      <div className="absolute right-0 top-1/2 -translate-y-1/2 flex flex-col gap-2 bg-slate-900/95 p-2 rounded border border-slate-500 shadow-2xl z-50 animate-in fade-in zoom-in duration-200">
                          <button className="p-3 bg-white/10 hover:bg-white/20 rounded text-green-400" onClick={(e) => { e.stopPropagation(); dispatch({type: 'ADD_SCORE', team: 'away', amount: 1})}}><Plus size={24}/></button>
                          <button className="p-3 bg-white/10 hover:bg-white/20 rounded text-red-400" onClick={(e) => { e.stopPropagation(); dispatch({type: 'ADD_SCORE', team: 'away', amount: -1})}}><Minus size={24}/></button>
                      </div>
                   )}
                </div>

                <div 
                    className="mt-auto text-sm text-slate-300 border-t border-white/20 pt-3 flex justify-between items-end cursor-pointer hover:bg-white/5 rounded px-2 transition-colors"
                    onClick={awayRole === 'AT BAT' ? handleBatterClick : handlePitcherStatClick}
                >
                   <div className="flex flex-col overflow-hidden">
                      <span className={`text-xs font-bold uppercase tracking-widest ${awayRole === 'AT BAT' ? 'text-green-400' : 'text-red-400'}`}>{awayRole}</span>
                      <span className="text-2xl lg:text-3xl text-white font-semibold truncate pr-2 font-display">{awayPlayer.name} #{awayPlayer.number}</span>
                   </div>
                   <span className="text-3xl lg:text-4xl font-display text-yellow-500">{awayPlayer.stat}</span>
                </div>
            </div>
          </div>

          {/* CENTER: Info */}
          <div className="w-[280px] lg:w-[320px] shrink-0 bg-slate-800 flex flex-col relative border-x-2 border-slate-900 shadow-[inset_0_0_20px_rgba(0,0,0,0.5)]">

            {/* Top: Inning & Timer */}
            <div className="h-20 lg:h-24 border-b border-slate-600 flex items-center justify-between px-4 bg-slate-800/80">
               <div 
                  className="relative flex items-center space-x-3 cursor-pointer hover:bg-slate-700/50 px-2 py-1 rounded transition-colors group" 
                  onClick={() => dispatch({type: 'NEXT_INNING'})}
                  onMouseEnter={() => setShowInningControls(true)}
                  onMouseLeave={() => setShowInningControls(false)}
               >
                 <div className="flex flex-col gap-1.5">
                    <div className={`w-0 h-0 border-l-[8px] border-l-transparent border-r-[8px] border-r-transparent ${state.isTop ? 'border-b-[12px] border-b-yellow-400' : 'border-b-[12px] border-b-slate-700'}`}></div>
                    <div className={`w-0 h-0 border-l-[8px] border-l-transparent border-r-[8px] border-r-transparent ${!state.isTop ? 'border-t-[12px] border-t-yellow-400' : 'border-t-[12px] border-t-slate-700'}`}></div>
                 </div>
                 <span className="text-5xl lg:text-6xl font-bold leading-none select-none text-slate-200 font-display">{state.inning}</span>

                 {showInningControls && (
                    <div className="absolute top-1/2 left-full ml-2 transform -translate-y-1/2 flex flex-col gap-1 bg-slate-900 p-1 rounded border border-slate-600 shadow-xl z-50">
                        <button className="p-1 hover:bg-white/20 rounded" onClick={(e) => { e.stopPropagation(); dispatch({type: 'SET_INNING', value: state.inning + 1}) }}><Plus size={16}/></button>
                        <button className="p-1 hover:bg-white/20 rounded" onClick={(e) => { e.stopPropagation(); dispatch({type: 'SET_INNING', value: Math.max(1, state.inning - 1)}) }}><Minus size={16}/></button>
                    </div>
                 )}
               </div>

               {/* Timer */}
               <div 
                  className={`flex items-center space-x-1 px-3 py-1.5 rounded border cursor-pointer select-none active:scale-95 transition-all ${state.timer <= 8 && state.isTimerRunning ? 'bg-red-900/80 border-red-500 animate-pulse' : 'bg-black/40 border-slate-600/50'}`}
                  onMouseDown={handleTimerMouseDown}
                  onMouseUp={handleTimerMouseUp}
                  onMouseLeave={handleTimerMouseUp}
                  onTouchStart={handleTimerMouseDown}
                  onTouchEnd={handleTimerMouseUp}
                  onClick={handleTimerClick}
               >
                    <span className={`text-5xl lg:text-6xl font-display font-bold w-[70px] text-center ${state.timer <= 8 ? 'text-white' : 'text-yellow-400'}`}>
                      {state.timer}
                    </span>
               </div>
            </div>

            {/* Middle: Bases & Counts */}
            <div className="flex-1 flex flex-col items-center justify-center p-2 relative gap-4">
                <div className="flex-1 flex items-center justify-center w-full">
                   <Diamond 
                      bases={state.bases} 
                      onToggle={(idx) => dispatch({type: 'TOGGLE_BASE', baseIndex: idx})}
                      className="scale-100" 
                      activeColor={activeBaseColor}
                   />
                </div>

                <div className="w-full flex justify-center pb-6">
                    <div className="flex flex-col space-y-3 items-start pl-6">
                        {/* Balls */}
                        <div className="flex items-center gap-4 cursor-pointer group" onClick={handleBallClick}>
                            <span className="text-4xl lg:text-5xl font-bold text-slate-500 group-hover:text-white transition-colors w-8 text-center font-display">B</span>
                            <div className="flex space-x-3">
                                {[0, 1, 2].map(i => (
                                <div key={i} className={`w-8 h-8 lg:w-10 lg:h-10 rounded-full border-2 border-slate-600 transition-all duration-100 ${i < state.balls ? 'bg-led-green shadow-[0_0_15px_#00ff41] border-transparent' : 'bg-slate-900'}`} />
                                ))}
                            </div>
                        </div>
                        {/* Strikes */}
                        <div className="flex items-center gap-4 cursor-pointer group" onClick={handleStrikeClick}>
                            <span className="text-4xl lg:text-5xl font-bold text-slate-500 group-hover:text-white transition-colors w-8 text-center font-display">S</span>
                            <div className="flex space-x-3">
                                {[0, 1].map(i => (
                                <div key={i} className={`w-8 h-8 lg:w-10 lg:h-10 rounded-full border-2 border-slate-600 transition-all duration-100 ${i < state.strikes ? 'bg-led-yellow shadow-[0_0_15px_#ffcc00] border-transparent' : 'bg-slate-900'}`} />
                                ))}
                            </div>
                        </div>
                        {/* Outs */}
                        <div className="flex items-center gap-4 cursor-pointer group" onClick={handleOutClick}>
                            <span className="text-4xl lg:text-5xl font-bold text-slate-500 group-hover:text-white transition-colors w-8 text-center font-display">O</span>
                            <div className="flex space-x-3">
                                {[0, 1].map(i => (
                                <div key={i} className={`w-8 h-8 lg:w-10 lg:h-10 rounded-full border-2 border-slate-600 transition-all duration-100 ${i < state.outs ? 'bg-led-red shadow-[0_0_15px_#ff3b30] border-transparent' : 'bg-slate-900'}`} />
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
          </div>

          {/* RIGHT: Home Team */}
          <div className="flex-1 border-l-2 border-slate-700 relative group overflow-hidden">
             <div className="absolute inset-0 opacity-20 transition-colors duration-500" style={{ backgroundColor: state.homeTeam.color }}></div>

             <div className="flex h-full p-4 lg:p-5 flex-col justify-between text-right relative z-10">
                <div className="flex justify-end items-start gap-4">
                   <div className="flex flex-col items-end min-w-0 pt-1">
                      <span className="text-5xl lg:text-6xl xl:text-7xl font-bold text-white tracking-tight drop-shadow-sm leading-none truncate">{state.homeTeam.name}</span>
                      <span className="text-sm lg:text-base text-slate-300 font-semibold tracking-wide uppercase truncate max-w-full pr-1">{state.homeTeam.fullName}</span>
                   </div>

                   <div className="shrink-0 relative">
                      <TeamLogo team={state.homeTeam} />
                      {!state.isTop && <div className="absolute -bottom-2 -left-2 w-5 h-5 bg-yellow-400 rounded-full animate-pulse shadow-[0_0_12px_rgba(250,204,21,1)] border-2 border-slate-900 z-20" />}
                   </div>
                </div>

                {/* Score Area */}
                <div 
                   className="flex-1 flex items-center justify-center relative group/score px-8"
                   onMouseDown={() => handleScoreMouseDown('home')}
                   onMouseUp={handleScoreMouseUp}
                   onTouchStart={() => handleScoreMouseDown('home')}
