```tsx
import React, { useRef, useEffect, useState, forwardRef } from 'react';
import { GameState, ActionType, Team } from '../types';
import { Diamond } from './Diamond';
import { Timer, Plus, Minus } from 'lucide-react';

interface ScoreboardDisplayProps {
  state: GameState;
  dispatch: React.Dispatch<ActionType>;
}

// Simple Audio Context Helper
const playBeep = (freq: number, duration: number, type: 'sine' | 'square' | 'triangle' = 'sine') => {
  try {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = type;
      osc.frequency.value = freq;

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();

      // Fade out
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.00001, ctx.currentTime + duration);

      osc.stop(ctx.currentTime + duration);
  } catch (e) {
      console.error("Audio playback failed", e);
  }
};

// Helper for Score Animation
const AnimatedScore = ({ score, color }: { score: number, color?: string }) => {
    const [animate, setAnimate] = useState(false);
    const prevScore = useRef(score);

    useEffect(() => {
        // Only animate if score has CHANGED from previous value
        if (score !== prevScore.current) {
            setAnimate(true);
            const timer = setTimeout(() => setAnimate(false), 500); // 500ms flash
            prevScore.current = score;
            return () => clearTimeout(timer);
        }
    }, [score]);

    return (
        <div 
          className={`flex items-center justify-center w-full h-full text-8xl lg:text-9xl xl:text-[9rem] font-bold text-center cursor-pointer select-none transition-all drop-shadow-lg leading-none rounded-lg ${animate ? 'scale-150 duration-150 z-50' : 'duration-300'}`}
          style={{ 
             color: animate ? '#fde047' : 'white', // Yellow flash
             textShadow: animate ? `0 0 40px ${color || '#fde047'}` : 'none'
          }}
        >
          {score}
        </div>
    );
};

// Helper for Indicator Animation (Ball/Strike/Out)
const AnimatedIndicator = ({ active, colorClass, shadowClass, baseClass }: { active: boolean, colorClass: string, shadowClass: string, baseClass: string }) => {
    const [animate, setAnimate] = useState(false);
    const mounted = useRef(false);

    useEffect(() => {
        if (!mounted.current) {
            mounted.current = true;
            return;
        }
        if (active) {
            setAnimate(true);
            const timer = setTimeout(() => setAnimate(false), 300);
            return () => clearTimeout(timer);
        }
    }, [active]);

    return (
        <div className={`${baseClass} ${active ? `${colorClass} ${shadowClass} border-transparent` : 'bg-slate-900 border-slate-600'} ${animate ? 'scale-150 brightness-150 duration-150' : 'duration-300'} transition-all`} />
    );
};

export const ScoreboardDisplay = forwardRef<HTMLDivElement, ScoreboardDisplayProps>(({ state, dispatch }, ref) => {
  const [showInningControls, setShowInningControls] = useState(false);
  const [showScoreControlsHome, setShowScoreControlsHome] = useState(false);
  const [showScoreControlsAway, setShowScoreControlsAway] = useState(false);

  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const ignoreTimerClickRef = useRef(false);

  // Score Interaction Refs
  const scoreTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const ignoreScoreClickRef = useRef(false);

  // Audio Effects for Timer
  useEffect(() => {
    if (!state.isTimerRunning) return;

    if (state.timer === 8) {
        playBeep(800, 0.2, 'sine'); // Warning beep
    } else if (state.timer === 0) {
        playBeep(300, 0.8, 'square'); // Time up buzzer
    }
  }, [state.timer, state.isTimerRunning]);

  // Timer Click Logic
  const handleTimerMouseDown = () => {
    ignoreTimerClickRef.current = false;
    timerRef.current = setTimeout(() => {
      dispatch({ type: 'SET_TIMER', value: 20 }); 
      if (state.isTimerRunning) dispatch({ type: 'TOGGLE_TIMER' }); 
      ignoreTimerClickRef.current = true;
    }, 800);
  };

  const handleTimerMouseUp = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  };

  const handleTimerClick = () => {
    if (!ignoreTimerClickRef.current) {
        dispatch({ type: 'TOGGLE_TIMER' });
    }
    ignoreTimerClickRef.current = false;
