export interface Player {
  id: string;
  name: string;
  number: string;
  stat: string; // e.g., "1-1" for batter, "P:60" for pitcher
  position?: string;
}

export interface Team {
  name: string; // Abbreviation e.g. "LSP"
  fullName: string;
  score: number;
