  currentBatterIndex: number;
}

export interface PitchInfo {
  type: string;
  speed: string;
  unit: string;
  spinRate: string;
}

export interface GameMeta {
  leagueName: string;
  date: string;
  gameId: string;
  broadcaster: string;
}

export interface GameState {
  awayTeam: Team;
  homeTeam: Team;

  // Inning
  inning: number;
  isTop: boolean; // true = top, false = bottom

  // Count
  balls: number;
  strikes: number;
  outs: number;

  // Runners (true = occupied)
  bases: [boolean, boolean, boolean]; // 1st, 2nd, 3rd

  // Active Players
  pitcher: Player;
  batter: Player;

  // Pitch Data
  currentPitch: PitchInfo;

  // Timer
  timer: number;
  isTimerRunning: boolean;

  // Display Settings
  showPitchInfo: boolean;
  displayMode: 'default' | 'lineup';

  meta: GameMeta;
}

export type ActionType = 
  | { type: 'INCREMENT_BALL' }
  | { type: 'INCREMENT_STRIKE' }
  | { type: 'INCREMENT_OUT' }
  | { type: 'RESET_COUNT' }
  | { type: 'TOGGLE_BASE'; baseIndex: 0 | 1 | 2 }
  | { type: 'ADD_SCORE'; team: 'home' | 'away'; amount: number }
  | { type: 'NEXT_INNING' }
  | { type: 'SET_INNING'; value: number }
  | { type: 'UPDATE_PLAYER'; role: 'pitcher' | 'batter'; field: keyof Player; value: string }
  | { type: 'INCREMENT_PLAYER_STAT'; role: 'pitcher' | 'batter' }
  | { type: 'UPDATE_TEAM'; team: 'home' | 'away'; field: keyof Team; value: any } // value can be string or number or array
  | { type: 'UPDATE_PITCH'; field: keyof PitchInfo; value: string }
  | { type: 'SET_TIMER'; value: number }
  | { type: 'TOGGLE_TIMER' }
  | { type: 'DECREMENT_TIMER' }
  | { type: 'TOGGLE_VISIBILITY'; field: 'showPitchInfo' }
  | { type: 'NEXT_BATTER' }
  | { type: 'ADD_PLAYER_TO_LINEUP'; team: 'home' | 'away' }
  | { type: 'UPDATE_LINEUP_PLAYER'; team: 'home' | 'away'; index: number; field: keyof Player; value: string }
  | { type: 'REMOVE_PLAYER_FROM_LINEUP'; team: 'home' | 'away'; index: number }
  | { type: 'UPDATE_META'; field: keyof GameMeta; value: string }
  | { type: 'SET_DISPLAY_MODE'; mode: 'default' | 'lineup' };

import React, { useReducer, useEffect, useRef } from 'react';
import { GameState, ActionType, Player } from './types';
import { INITIAL_STATE } from './constants';
import { ScoreboardDisplay } from './components/ScoreboardDisplay';
import { ScoreboardControls } from './components/ScoreboardControls';
import { MonitorPlay, Maximize } from 'lucide-react';

const generateId = () => Math.random().toString(36).substr(2, 9);

// Helper to increment pitch stat string "P: 60" -> "P: 61"
const incrementPitchStat = (stat: string): string => {
  const match = stat.match(/P:\s*(\d+)/i);
  if (match) {
    const count = parseInt(match[1]);
    return `P: ${count + 1}`;
  }
  // Fallback if format is different, just try to parse int
  const count = parseInt(stat);
  if (!isNaN(count)) return (count + 1).toString();
  return stat;
};

// Reducer function
function reducer(state: GameState, action: ActionType): GameState {
  switch (action.type) {
    case 'INCREMENT_BALL':
      if (state.balls >= 3) return { ...state, balls: 0 };
      return { 
        ...state, 
        balls: state.balls + 1,
      };

    case 'INCREMENT_STRIKE':
      // Cycle 0 -> 1 -> 2 -> 0. No auto-out.
      const nextStrike = state.strikes >= 2 ? 0 : state.strikes + 1;
      return { 
        ...state, 
        strikes: nextStrike,
      };

    case 'INCREMENT_OUT':
      // After 2 outs, if clicked again (3rd out), reset outs/balls/strikes/bases, but DO NOT flip inning automatically.
      // User must manually press "Next Inning".
      if (state.outs >= 2) {
        return { 
          ...state, 
          outs: 0, 
          balls: 0, 
          strikes: 0, 
          bases: [false, false, false],
        };
      }
      return { 
        ...state, 
        outs: state.outs + 1,
      };

    case 'RESET_COUNT':
      return { ...state, balls: 0, strikes: 0 };

    case 'TOGGLE_BASE':
      const newBases = [...state.bases] as [boolean, boolean, boolean];
      newBases[action.baseIndex] = !newBases[action.baseIndex];
      return { ...state, bases: newBases };

    case 'ADD_SCORE':
      if (action.team === 'home') {
        return { ...state, homeTeam: { ...state.homeTeam, score: Math.max(0, state.homeTeam.score + action.amount) } };
      } else {
        return { ...state, awayTeam: { ...state.awayTeam, score: Math.max(0, state.awayTeam.score + action.amount) } };
      }

    case 'NEXT_INNING':
      return { 
        ...state, 
        isTop: !state.isTop, 
        inning: state.isTop ? state.inning : state.inning + 1,
        balls: 0, strikes: 0, outs: 0, bases: [false, false, false],
        isTimerRunning: false,
        timer: 20
      };

    case 'SET_INNING':
       return { ...state, inning: action.value };

    case 'UPDATE_PLAYER':
      return { ...state, [action.role]: { ...state[action.role], [action.field]: action.value } };

    case 'INCREMENT_PLAYER_STAT':
      if (action.role === 'pitcher') {
        // Logic: Pitcher is in the defense team.
        return { ...state, pitcher: { ...state.pitcher, stat: incrementPitchStat(state.pitcher.stat) } };
      }
      return state;

    case 'UPDATE_TEAM':
      const teamKey = action.team === 'home' ? 'homeTeam' : 'awayTeam';
      return { ...state, [teamKey]: { ...state[teamKey], [action.field]: action.value } };

    case 'UPDATE_PITCH':
      return { ...state, currentPitch: { ...state.currentPitch, [action.field]: action.value } };

    case 'UPDATE_META':
      return { ...state, meta: { ...state.meta, [action.field]: action.value } };

    case 'SET_TIMER':
      return { ...state, timer: action.value };

    case 'TOGGLE_TIMER':
      return { ...state, isTimerRunning: !state.isTimerRunning };

    case 'DECREMENT_TIMER':
      return { ...state, timer: Math.max(0, state.timer - 1) };

    case 'TOGGLE_VISIBILITY':
      return { ...state, [action.field]: !state[action.field] };

    case 'NEXT_BATTER': {
      const isTop = state.isTop;
      const tKey = isTop ? 'awayTeam' : 'homeTeam';
      const teamObj = state[tKey];
      if (teamObj.lineup.length === 0) return state;

      const nextIndex = (teamObj.currentBatterIndex + 1) % teamObj.lineup.length;
      const nextBatter = teamObj.lineup[nextIndex];

      return {
        ...state,
        [tKey]: { ...teamObj, currentBatterIndex: nextIndex },
        batter: { ...nextBatter, stat: state.batter.stat } 
      };
    }

    case 'ADD_PLAYER_TO_LINEUP': {
      const tKey = action.team === 'home' ? 'homeTeam' : 'awayTeam';
      const newPlayer: Player = { id: generateId(), name: 'New Player', number: '00', stat: '.000' };
      return {
        ...state,
        [tKey]: { ...state[tKey], lineup: [...state[tKey].lineup, newPlayer] }
      };
    }

    case 'UPDATE_LINEUP_PLAYER': {
      const tKey = action.team === 'home' ? 'homeTeam' : 'awayTeam';
      const newLineup = [...state[tKey].lineup];
      if (newLineup[action.index]) {
        newLineup[action.index] = { ...newLineup[action.index], [action.field]: action.value };
      }
      return {
        ...state,
        [tKey]: { ...state[tKey], lineup: newLineup }
      };
    }

    case 'REMOVE_PLAYER_FROM_LINEUP': {
      const tKey = action.team === 'home' ? 'homeTeam' : 'awayTeam';
      const newLineup = state[tKey].lineup.filter((_, i) => i !== action.index);
      return {
        ...state,
        [tKey]: { ...state[tKey], lineup: newLineup }
      };
    }

    case 'SET_DISPLAY_MODE':
      return { ...state, displayMode: action.mode };

    default:
      return state;
  }
}

export const App: React.FC = () => {
  const [state, dispatch] = useReducer(reducer, INITIAL_STATE);
  const displayRef = useRef<HTMLDivElement>(null);

  // Timer Effect
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (state.isTimerRunning && state.timer > 0) {
      interval = setInterval(() => {
        dispatch({ type: 'DECREMENT_TIMER' });
      }, 1000);
    } else if (state.timer === 0 && state.isTimerRunning) {
      dispatch({ type: 'TOGGLE_TIMER' }); // Stop when reached 0
    }
    return () => clearInterval(interval);
  }, [state.isTimerRunning, state.timer]);

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
       // Request fullscreen on the display element if it exists, otherwise fallback to root
       if (displayRef.current) {
