        <div className="w-full h-full flex flex-col lg:flex-row gap-0 overflow-hidden">
          {/* Left/Top: Display */}
          <div className="flex-none lg:flex-[2] p-4 bg-slate-950 flex flex-col items-center justify-center overflow-hidden border-b lg:border-b-0 lg:border-r border-slate-700">
