                {/* Middle: Diamond & Stats */}
                <div className="flex-1 flex items-center justify-center relative">
                    <div className="scale-75 lg:scale-90">
                       <Diamond 
                          bases={state.bases} 
                          onToggle={(idx) => dispatch({type: 'TOGGLE_BASE', baseIndex: idx})}
                          activeColor={activeBaseColor}
                       />
                    </div>

                    {/* Count Overlay */}
                    <div className="absolute bottom-4 left-0 right-0 flex justify-center space-x-8">
                         <div className="flex flex-col items-center">
                             <div className="flex space-x-1 mb-1">
                                {[0,1,2].map(i => (
                                    <AnimatedIndicator 
                                        key={i}
