                          <div className="flex flex-col items-center">
                             <div className="flex space-x-1 mb-1">
                                {[0,1].map(i => (
                                     <AnimatedIndicator 
                                        key={i}
                                        active={i < state.outs} 
                                        colorClass="bg-red-500" 
                                        shadowClass="shadow-[0_0_10px_#ef4444]" 
                                        baseClass="w-4 h-4 rounded-full"
