                   />
                </div>

                <div className="w-full flex justify-center pb-0 shrink-0">
                    <div className="flex flex-col space-y-1 lg:space-y-2 items-start pl-8">
                        {/* Balls */}
                        <div className="flex items-center gap-3 lg:gap-4 cursor-pointer group" onClick={handleBallClick}>
                            <span className="text-3xl lg:text-4xl font-bold text-slate-500 group-hover:text-white transition-colors w-8 text-center">B</span>
                            <div className="flex space-x-2 lg:space-x-3">
                                {[0, 1, 2].map(i => (
                                    <AnimatedIndicator 
                                        key={i}
                                        active={i < state.balls} 
                                        colorClass="bg-led-green" 
                                        shadowClass="shadow-[0_0_20px_#00ff41]" 
                                        baseClass="w-8 h-8 lg:w-10 lg:h-10 rounded-full border-[3px]"
                                    />
                                ))}
                            </div>
                        </div>
                        {/* Strikes */}
                        <div className="flex items-center gap-3 lg:gap-4 cursor-pointer group" onClick={handleStrikeClick}>
                            <span className="text-3xl lg:text-4xl font-bold text-slate-500 group-hover:text-white transition-colors w-8 text-center">S</span>
                            <div className="flex space-x-2 lg:space-x-3">
                                {[0, 1].map(i => (
                                    <AnimatedIndicator 
                                        key={i}
                                        active={i < state.strikes} 
                                        colorClass="bg-led-yellow" 
                                        shadowClass="shadow-[0_0_20px_#ffcc00]" 
                                        baseClass="w-8 h-8 lg:w-10 lg:h-10 rounded-full border-[3px]"
                                    />
                                ))}
                            </div>
                        </div>
                        {/* Outs */}
                        <div className="flex items-center gap-3 lg:gap-4 cursor-pointer group" onClick={handleOutClick}>
                            <span className="text-3xl lg:text-4xl font-bold text-slate-500 group-hover:text-white transition-colors w-8 text-center">O</span>
                            <div className="flex space-x-2 lg:space-x-3">
                                {[0, 1].map(i => (
                                    <AnimatedIndicator 
                                        key={i}
                                        active={i < state.outs} 
                                        colorClass="bg-led-red" 
                                        shadowClass="shadow-[0_0_20px_#ff3b30]" 
                                        baseClass="w-8 h-8 lg:w-10 lg:h-10 rounded-full border-[3px]"
                                    />
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
          </div>

          {/* RIGHT: Home Team */}
          <div className="flex-1 border-l-2 border-slate-700 relative group overflow-hidden">
             <div className="absolute inset-0 opacity-20 transition-colors duration-500" style={{ backgroundColor: state.homeTeam.color }}></div>

             <div className="flex h-full p-4 lg:p-5 flex-col justify-between text-right relative z-10">
                <div className="flex justify-end items-start gap-4">
                   <div className="flex flex-col items-end min-w-0 pt-1">
                      <span className="text-5xl lg:text-6xl xl:text-7xl font-bold text-white tracking-tight drop-shadow-sm leading-none truncate">{state.homeTeam.name}</span>
                      <span className="text-sm lg:text-base text-slate-300 font-semibold tracking-wide uppercase truncate max-w-full pr-1">{state.homeTeam.fullName}</span>
                   </div>

                   <div className="shrink-0 relative">
                      <TeamLogo team={state.homeTeam} />
                      {!state.isTop && <div className="absolute -bottom-2 -left-2 w-5 h-5 bg-yellow-400 rounded-full animate-pulse shadow-[0_0_12px_rgba(250,204,21,1)] border-2 border-slate-900 z-20" />}
                   </div>
                </div>

                {/* Score Area */}
                <div 
                   className="flex-1 flex items-center justify-center relative group/score px-8"
                   onMouseDown={() => handleScoreMouseDown('home')}
                   onMouseUp={handleScoreMouseUp}
                   onMouseLeave={handleScoreMouseLeave}
                   onTouchStart={() => handleScoreMouseDown('home')}
                   onTouchEnd={handleScoreMouseUp}
                   onClick={() => handleScoreClick('home')}
                >
                   <AnimatedScore score={state.homeTeam.score} color={state.homeTeam.color} />

                   {showScoreControlsHome && (
                      <div className="absolute left-0 top-1/2 -translate-y-1/2 flex flex-col gap-2 bg-slate-900/95 p-2 rounded border border-slate-500 shadow-2xl z-50 animate-in fade-in zoom-in duration-200">
                          <button className="p-3 bg-white/10 hover:bg-white/20 rounded text-green-400" onClick={(e) => { e.stopPropagation(); dispatch({type: 'ADD_SCORE', team: 'home', amount: 1})}}><Plus size={24}/></button>
                          <button className="p-3 bg-white/10 hover:bg-white/20 rounded text-red-400" onClick={(e) => { e.stopPropagation(); dispatch({type: 'ADD_SCORE', team: 'home', amount: -1})}}><Minus size={24}/></button>
                      </div>
                   )}
                </div>

                 <div 
                    className="mt-auto text-sm text-slate-300 border-t border-white/20 pt-3 flex justify-between items-end flex-row-reverse cursor-pointer hover:bg-white/5 rounded px-2 transition-colors"
                    onClick={homeRole === 'AT BAT' ? handleBatterClick : handlePitcherStatClick}
                 >
                   <div className="flex flex-col items-end overflow-hidden">
                      <span className={`text-xs font-bold uppercase tracking-widest ${homeRole === 'AT BAT' ? 'text-green-400' : 'text-red-400'}`}>{homeRole}</span>
                      <span className="text-2xl lg:text-3xl text-white font-semibold truncate pl-2 font-display">{homePlayer.name} #{homePlayer.number}</span>
                   </div>
                   <span className="text-3xl lg:text-4xl font-display text-yellow-500">{homePlayer.stat}</span>
                </div>
            </div>
          </div>

        </div>

        {/* Bottom Section: Detailed Stats - Render only if active */}
        {state.showPitchInfo && (
          <div className="grid grid-cols-12 bg-slate-950 divide-x-2 divide-slate-800 border-t-2 border-slate-700 min-h-[90px] lg:min-h-[110px] shrink-0">

              {/* Current Pitch Info */}
              <div className="col-span-8 p-3 lg:p-4 bg-slate-900/50 flex flex-col justify-center">
                <div className="text-xs text-slate-500 uppercase tracking-wider mb-1 font-bold">Last Pitch</div>
                <div className="flex flex-col space-y-0">
                  <div className="flex justify-between items-end">
                      <span className="text-2xl lg:text-3xl font-bold text-cyan-400 font-display truncate">{state.currentPitch.type}</span>
                      <span className="text-lg font-display text-slate-400">{state.currentPitch.spinRate}</span>
                  </div>
                  <div className="flex items-baseline space-x-2">
                      <span className="text-4xl lg:text-5xl font-display font-bold text-white">{state.currentPitch.speed}</span>
                      <span className="text-lg lg:text-xl text-slate-400 font-medium font-display">{state.currentPitch.unit}</span>
                    </div>
                </div>
              </div>

              {/* Game Meta */}
              <div className="col-span-4 flex flex-col justify-center p-3 lg:p-4 bg-slate-900/50 space-y-1">
                <div className="flex justify-between items-center border-b border-slate-800 pb-2 mb-1">
                  <span className="text-[10px] lg:text-xs text-slate-500">LEAGUE</span>
                  <span className="text-base lg:text-lg font-semibold text-white font-display truncate">{state.meta.leagueName}</span>
                </div>
                  <div className="flex justify-between items-center">
                  <span className="text-[10px] lg:text-xs text-slate-500">GAME ID</span>
                  <span className="font-display text-base lg:text-lg text-yellow-500/80">{state.meta.gameId}</span>
                </div>
                <div className="flex items-center justify-between pt-1">
                    <span className="text-[10px] lg:text-xs text-slate-500 truncate max-w-[80px]">{state.meta.broadcaster}</span>
                    <div className="flex items-center space-x-2">
                        <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></span>
                        <span className="text-[10px] lg:text-xs font-bold text-red-500 tracking-widest">LIVE</span>
                    </div>
                </div>
              </div>
          </div>
        )}

      </div>
      )
  };

  const renderLineupView = () => {
    // 3-Column Layout: Lineup | Center | Lineup
    const activeBatterId = state.isTop ? state.awayTeam.lineup[state.awayTeam.currentBatterIndex]?.id : state.homeTeam.lineup[state.homeTeam.currentBatterIndex]?.id;

    const LineupColumn = ({ team, isAway }: { team: Team, isAway: boolean }) => {
        const isTeamPitching = isAway ? !state.isTop : state.isTop;

        return (
            <div className="flex-1 flex flex-col h-full bg-slate-950 border-r border-slate-800 relative">
                {/* Header */}
                <div className="p-3 border-b border-slate-800 flex items-center gap-3 relative overflow-hidden">
                     <div className="absolute inset-0 opacity-20" style={{ backgroundColor: team.color }}></div>
                     <TeamLogo team={team} />
                     <div className="flex flex-col relative z-10">
                         <span className="text-3xl font-bold leading-none">{team.name}</span>
                         <span className="text-xs text-slate-400 font-bold uppercase">{team.fullName}</span>
                     </div>
                </div>

                {/* Lineup List */}
                <div className="flex-1 overflow-y-auto no-scrollbar p-2 space-y-1">
                    {team.lineup.map((p, idx) => (
                        <div 
                            key={p.id} 
                            className={`flex items-center p-1 rounded ${p.id === activeBatterId ? 'bg-yellow-500 text-black shadow-lg scale-[1.02] font-bold' : 'text-slate-400 bg-white/5'}`}
                        >
                            <span className={`w-6 text-center text-sm font-mono ${p.id === activeBatterId ? 'text-black' : 'text-slate-500'}`}>{idx+1}</span>
                             <span className={`w-8 text-center text-xs font-bold uppercase ${p.id === activeBatterId ? 'text-black/70' : 'text-slate-600'}`}>{p.position}</span>
                            <span className="flex-1 text-sm truncate px-1">{p.name}</span>
                            <span className={`text-xs ${p.id === activeBatterId ? 'text-black' : 'text-slate-500'}`}>{p.stat}</span>
                        </div>
                    ))}
                </div>

                {/* Pitcher Slot (Bottom) */}
                <div className="p-2 border-t border-slate-800 bg-slate-900 mt-auto">
                    {isTeamPitching ? (
                        <div className="flex items-center justify-between bg-red-900/20 border border-red-900/50 p-2 rounded">
                            <div className="flex flex-col">
                                <span className="text-[10px] text-red-400 font-bold uppercase tracking-widest">Pitching</span>
                                <span className="text-white font-bold">{state.pitcher.name} #{state.pitcher.number}</span>
                            </div>
                            <span className="text-xl text-yellow-500 font-display">{state.pitcher.stat}</span>
                        </div>
                    ) : (
                         <div className="p-2 h-[58px] flex items-center justify-center opacity-30">
                            <span className="text-xs text-slate-600 uppercase">Batting</span>
                         </div>
                    )}
                </div>
            </div>
        );
    };

    return (
        <div className="w-full h-full bg-slate-900 border-4 border-slate-700 rounded-xl overflow-hidden shadow-2xl flex flex-row font-display text-white">

            {/* Left: Away Lineup */}
            <div className="flex-[0.8] lg:flex-1 h-full min-w-0 border-r-2 border-slate-700">
                <LineupColumn team={state.awayTeam} isAway={true} />
            </div>

            {/* Center: Simplified Scoreboard */}
            <div className="flex-[1.2] lg:flex-[1.5] h-full flex flex-col bg-slate-800 min-w-0">
                {/* Score Strip */}
                <div className="h-20 bg-slate-950 flex border-b-2 border-slate-700 shrink-0">
                    {/* Away Score */}
                    <div className="flex-1 flex items-center justify-center text-5xl lg:text-7xl font-bold relative overflow-hidden" style={{ color: state.awayTeam.color }}>
                         <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent opacity-20"></div>
                         <div className="z-10"><AnimatedScore score={state.awayTeam.score} color={state.awayTeam.color} /></div>
                    </div>
                    {/* Inning */}
                    <div className="w-24 bg-slate-900 flex flex-col items-center justify-center border-x border-slate-700">
                        <div className="flex flex-col gap-1 mb-1">
                            <div className={`w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent ${state.isTop ? 'border-b-[8px] border-b-yellow-400' : 'border-b-[8px] border-b-slate-700'}`}></div>
                            <div className={`w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent ${!state.isTop ? 'border-t-[8px] border-t-yellow-400' : 'border-t-[8px] border-t-slate-700'}`}></div>
                         </div>
                        <span className="text-3xl font-bold text-slate-200">{state.inning}</span>
                    </div>
                    {/* Home Score */}
                    <div className="flex-1 flex items-center justify-center text-5xl lg:text-7xl font-bold relative overflow-hidden" style={{ color: state.homeTeam.color }}>
                        <div className="absolute inset-0 bg-gradient-to-l from-transparent via-white/5 to-transparent opacity-20"></div>
                        <div className="z-10"><AnimatedScore score={state.homeTeam.score} color={state.homeTeam.color} /></div>
                    </div>
                </div>

                {/* Middle: Diamond & Stats */}
                <div className="flex-1 flex items-center justify-center relative">
                    <div className="scale-75 lg:scale-90">
                       <Diamond 
                          bases={state.bases} 
                          onToggle={(idx) => dispatch({type: 'TOGGLE_BASE', baseIndex: idx})}
                          activeColor={activeBaseColor}
                       />
                    </div>

                    {/* Count Overlay */}
                    <div className="absolute bottom-4 left-0 right-0 flex justify-center space-x-8">
                         <div className="flex flex-col items-center">
                             <div className="flex space-x-1 mb-1">
                                {[0,1,2].map(i => (
                                    <AnimatedIndicator 
                                        key={i}
                                        active={i < state.balls} 
                                        colorClass="bg-green-500" 
                                        shadowClass="shadow-[0_0_10px_#22c55e]" 
                                        baseClass="w-4 h-4 rounded-full"
                                    />
                                ))}
                             </div>
                             <span className="text-xs font-bold text-slate-500">BALL</span>
                         </div>
                          <div className="flex flex-col items-center">
                             <div className="flex space-x-1 mb-1">
                                {[0,1].map(i => (
                                     <AnimatedIndicator 
                                        key={i}
                                        active={i < state.strikes} 
                                        colorClass="bg-yellow-500" 
                                        shadowClass="shadow-[0_0_10px_#eab308]" 
                                        baseClass="w-4 h-4 rounded-full"
                                    />
                                ))}
                             </div>
                             <span className="text-xs font-bold text-slate-500">STRIKE</span>
                         </div>
                          <div className="flex flex-col items-center">
                             <div className="flex space-x-1 mb-1">
                                {[0,1].map(i => (
                                     <AnimatedIndicator 
                                        key={i}
                                        active={i < state.outs} 
                                        colorClass="bg-red-500" 
                                        shadowClass="shadow-[0_0_10px_#ef4444]" 
                                        baseClass="w-4 h-4 rounded-full"
                                    />
                                ))}
                             </div>
                             <span className="text-xs font-bold text-slate-500">OUT</span>
                         </div>
                    </div>
                </div>

                 {/* Pitch Info Bar */}
                 {state.showPitchInfo && (
                     <div className="h-16 bg-slate-950 border-t border-slate-700 flex items-center justify-between px-4 shrink-0">
                         <div className="flex flex-col">
                             <span className="text-[10px] text-slate-500 uppercase">Speed</span>
                             <span className="text-2xl font-bold text-white">{state.currentPitch.speed} <small className="text-sm text-slate-400">{state.currentPitch.unit}</small></span>
                         </div>
                         <div className="flex flex-col items-end">
                             <span className="text-[10px] text-slate-500 uppercase">Pitch</span>
                             <span className="text-xl font-bold text-cyan-400">{state.currentPitch.type}</span>
                         </div>
                     </div>
                 )}
            </div>

            {/* Right: Home Lineup */}
            <div className="flex-[0.8] lg:flex-1 h-full min-w-0 border-l-2 border-slate-700">
                <LineupColumn team={state.homeTeam} isAway={false} />
            </div>

        </div>
    )
  };

  return (
    <div ref={ref} className="w-full h-full">
        {state.displayMode === 'lineup' ? renderLineupView() : renderDefaultView()}
    </div>
  );
});
